#!/usr/bin/env python3
"""Offline WAN telemetry incident analyzer.

Reads UTF-8 JSON Lines from stdin, writes exactly one JSON object per line to
stdout.  Uses Z3 integer linear arithmetic for exact finite inference.
"""
import sys
import json
import re
from fractions import Fraction
from math import gcd

try:
    import z3
except Exception:  # pragma: no cover
    z3 = None

NAME_RE = re.compile(r'^[A-Za-z][A-Za-z0-9_-]{0,31}$')
METRICS = {"demand", "link", "ingress", "egress"}


def is_name(x):
    return isinstance(x, str) and NAME_RE.fullmatch(x) is not None


def is_int(x):
    return type(x) is int  # excludes bool


class Invalid(Exception):
    pass


def _reject_const(x):
    raise ValueError("nonstandard constant")


def parse_line(line):
    try:
        val = json.loads(line, parse_constant=_reject_const)
        return 'json', val
    except (ValueError, TypeError, RecursionError):
        return 'malformed', None


def validate(req):
    if not isinstance(req, dict):
        raise Invalid()
    rid = req.get('id', None)
    if not is_name(rid):
        raise Invalid()
    if not is_int(req.get('version')) or req.get('version') != 1:
        raise Invalid()

    nodes = req.get('nodes')
    if not isinstance(nodes, list) or not (2 <= len(nodes) <= 12):
        raise Invalid()
    for n in nodes:
        if not is_name(n):
            raise Invalid()
    if len(set(nodes)) != len(nodes):
        raise Invalid()
    nodeset = set(nodes)

    edges = req.get('edges')
    if not isinstance(edges, list) or len(edges) > 32:
        raise Invalid()
    edge_ids = []
    edge_set = set()
    edge_index = {}
    for e in edges:
        if not isinstance(e, dict):
            raise Invalid()
        eid = e.get('id')
        if not is_name(eid) or eid in edge_set:
            raise Invalid()
        s = e.get('source')
        t = e.get('target')
        if s not in nodeset or t not in nodeset or s == t:
            raise Invalid()
        cap = e.get('capacity')
        if not is_int(cap) or not (0 <= cap <= 1000000):
            raise Invalid()
        edge_index[eid] = len(edge_ids)
        edge_ids.append(eid)
        edge_set.add(eid)

    commodities = req.get('commodities')
    if not isinstance(commodities, list) or len(commodities) > 12:
        raise Invalid()
    comm_ids = []
    comm_set = set()
    comm_pairs = set()
    comm_data = []
    for c in commodities:
        if not isinstance(c, dict):
            raise Invalid()
        cid = c.get('id')
        if not is_name(cid) or cid in comm_set:
            raise Invalid()
        s = c.get('source')
        t = c.get('target')
        if s not in nodeset or t not in nodeset or s == t:
            raise Invalid()
        if (s, t) in comm_pairs:
            raise Invalid()
        routes = c.get('routes')
        if not isinstance(routes, list) or not (1 <= len(routes) <= 3):
            raise Invalid()
        parsed_routes = []
        wsum = 0
        for r in routes:
            if not isinstance(r, dict):
                raise Invalid()
            ed = r.get('edges')
            w = r.get('weight')
            if not isinstance(ed, list) or len(ed) < 1:
                raise Invalid()
            if not is_int(w) or not (1 <= w <= 8):
                raise Invalid()
            wsum += w
            cur = s
            visited = {s}
            for eid in ed:
                if not is_name(eid) or eid not in edge_set:
                    raise Invalid()
                ee = edges[edge_index[eid]]
                if ee['source'] != cur:
                    raise Invalid()
                cur = ee['target']
                if cur in visited:
                    raise Invalid()
                visited.add(cur)
            if cur != t:
                raise Invalid()
            parsed_routes.append((ed, w))
        if wsum > 8:
            raise Invalid()
        comm_pairs.add((s, t))
        comm_set.add(cid)
        comm_data.append({'id': cid, 'source': s, 'target': t, 'routes': parsed_routes})
        comm_ids.append(cid)

    domains = req.get('domains')
    if not isinstance(domains, list) or len(domains) > 14:
        raise Invalid()
    for d in domains:
        if not is_name(d):
            raise Invalid()
    if len(set(domains)) != len(domains):
        raise Invalid()
    domainset = set(domains)

    mf = req.get('max_faults')
    if not is_int(mf) or not (0 <= mf <= len(domains)):
        raise Invalid()

    snapshots = req.get('snapshots')
    if not isinstance(snapshots, list) or not (1 <= len(snapshots) <= 4):
        raise Invalid()
    snap_ids = set()
    snap_data = []
    total_obs = 0
    nc = len(comm_ids)
    for sn in snapshots:
        if not isinstance(sn, dict):
            raise Invalid()
        sid = sn.get('id')
        if not is_name(sid) or sid in snap_ids:
            raise Invalid()
        snap_ids.add(sid)
        bounds = sn.get('bounds')
        if not isinstance(bounds, list) or len(bounds) != nc:
            raise Invalid()
        bnd = []
        for b in bounds:
            if not isinstance(b, list) or len(b) != 2:
                raise Invalid()
            lo, hi = b[0], b[1]
            if not is_int(lo) or not is_int(hi) or not (0 <= lo <= hi <= 10000):
                raise Invalid()
            bnd.append((lo, hi))
        controller = sn.get('controller')
        if not isinstance(controller, list) or len(controller) != nc:
            raise Invalid()
        for v in controller:
            if not is_int(v) or not (0 <= v <= 10000):
                raise Invalid()
        tol = sn.get('tolerance')
        if not is_int(tol) or not (0 <= tol <= 10000):
            raise Invalid()
        obs = sn.get('observations')
        if not isinstance(obs, list) or len(obs) > 96:
            raise Invalid()
        obs_ids = set()
        parsed_obs = []
        for o in obs:
            if not isinstance(o, dict):
                raise Invalid()
            oid = o.get('id')
            if not is_name(oid) or oid in obs_ids:
                raise Invalid()
            obs_ids.add(oid)
            metric = o.get('metric')
            if not isinstance(metric, str) or metric not in METRICS:
                raise Invalid()
            target = o.get('target')
            if not is_name(target):
                raise Invalid()
            if metric == 'demand':
                if target not in comm_set:
                    raise Invalid()
            elif metric == 'link':
                if target not in edge_set:
                    raise Invalid()
            else:
                if target not in nodeset:
                    raise Invalid()
            lo = o.get('lower')
            hi = o.get('upper')
            if not is_int(lo) or not is_int(hi) or not (-1000000 <= lo <= hi <= 1000000):
                raise Invalid()
            dom = o.get('domain')
            if dom is None:
                pass
            elif not is_name(dom) or dom not in domainset:
                raise Invalid()
            parsed_obs.append({'metric': metric, 'target': target, 'lo': lo, 'hi': hi, 'domain': dom})
        total_obs += len(obs)
        if total_obs > 256:
            raise Invalid()
        snap_data.append({'id': sid, 'bounds': bnd, 'controller': controller,
                          'tolerance': tol, 'observations': parsed_obs})

    return {
        'id': rid, 'nodes': nodes, 'edges': edges, 'edge_ids': edge_ids,
        'edge_index': edge_index, 'commodities': comm_data, 'comm_ids': comm_ids,
        'domains': domains, 'max_faults': mf, 'snapshots': snap_data,
    }


def lcm(a, b):
    return a // gcd(a, b) * b


def frac_str(fr):
    return "%d/%d" % (fr.numerator, fr.denominator)


# ---------------------------------------------------------------------------
# Solver
# ---------------------------------------------------------------------------

def _prepare(req):
    edges = req['edges']
    edge_ids = req['edge_ids']
    edge_index = req['edge_index']
    commodities = req['commodities']
    comm_ids = req['comm_ids']
    nc = len(comm_ids)
    ne = len(edge_ids)
    W = [sum(w for (_, w) in c['routes']) for c in commodities]
    L = 1
    for w in W:
        L = lcm(L, w)
    coeff = [[0] * ne for _ in range(nc)]
    for ci, c in enumerate(commodities):
        wc = W[ci]
        for (ed, w) in c['routes']:
            add = L * w // wc
            for eid in ed:
                coeff[ci][edge_index[eid]] += add
    return L, coeff


def _link_expr(qrow, coeff, e, nc):
    expr = None
    for ci in range(nc):
        cf = coeff[ci][e]
        if cf:
            t = cf * qrow[ci]
            expr = t if expr is None else expr + t
    return expr


def _obs_expr_L(req, qrow, coeff, L, s, metric, target):
    commodities = req['commodities']
    comm_ids = req['comm_ids']
    edge_index = req['edge_index']
    nc = len(comm_ids)
    if metric == 'demand':
        return L * qrow[comm_ids.index(target)]
    if metric == 'link':
        e = edge_index[target]
        expr = _link_expr(qrow, coeff, e, nc)
        return expr if expr is not None else z3.IntVal(0)
    if metric == 'ingress':
        expr = None
        for ci, c in enumerate(commodities):
            if c['source'] == target:
                t = L * qrow[ci]
                expr = t if expr is None else expr + t
        return expr if expr is not None else z3.IntVal(0)
    if metric == 'egress':
        expr = None
        for ci, c in enumerate(commodities):
            if c['target'] == target:
                t = L * qrow[ci]
                expr = t if expr is None else expr + t
        return expr if expr is not None else z3.IntVal(0)
    raise RuntimeError('bad metric')


def solve(req):
    if z3 is None:
        raise RuntimeError("z3 unavailable")

    edges = req['edges']
    edge_ids = req['edge_ids']
    domains = req['domains']
    max_faults = req['max_faults']
    snapshots = req['snapshots']
    commodities = req['commodities']
    comm_ids = req['comm_ids']

    nc = len(comm_ids)
    ne = len(edge_ids)
    ns = len(snapshots)
    nd = len(domains)
    L, coeff = _prepare(req)

    # demand variables
    q = [[z3.Int('q_%d_%d' % (s, ci)) for ci in range(nc)] for s in range(ns)]

    base = []
    for s in range(ns):
        for ci in range(nc):
            lo, hi = snapshots[s]['bounds'][ci]
            base.append(q[s][ci] >= lo)
            base.append(q[s][ci] <= hi)
    for s in range(ns):
        for e in range(ne):
            cap = edges[e]['capacity']
            expr = _link_expr(q[s], coeff, e, nc)
            if expr is not None:
                base.append(expr <= L * cap)

    faulty = [z3.Bool('f_%d' % d) for d in range(nd)]
    domain_index = {d: i for i, d in enumerate(domains)}

    for s in range(ns):
        for o in snapshots[s]['observations']:
            expr = _obs_expr_L(req, q[s], coeff, L, s, o['metric'], o['target'])
            loL = L * o['lo']
            hiL = L * o['hi']
            inside = z3.And(expr >= loL, expr <= hiL)
            if o['domain'] is None:
                base.append(inside)
            else:
                base.append(z3.Or(inside, faulty[domain_index[o['domain']]]))

    sumf = z3.Sum([z3.If(f, 1, 0) for f in faulty]) if nd > 0 else z3.IntVal(0)

    # minimum faults
    opt = z3.Optimize()
    opt.add(base)
    h = opt.minimize(sumf)
    if opt.check() != z3.sat:
        return {'id': req['id'], 'status': 'infeasible'}
    k = opt.lower(h).as_long()
    if k > max_faults:
        return {'id': req['id'], 'status': 'infeasible'}

    base_k = base + [sumf == k]

    # enumerate all optimal fault sets
    fault_sets = []
    witness_model = None
    solver = z3.Solver()
    solver.add(base_k)
    while True:
        r = solver.check()
        if r != z3.sat:
            break
        m = solver.model()
        if witness_model is None:
            witness_model = m
        Sset = frozenset(d for d in range(nd) if z3.is_true(m.eval(faulty[d], model_completion=True)))
        fault_sets.append(Sset)
        # blocking clause over fault assignment
        block = []
        for d in range(nd):
            if d in Sset:
                block.append(z3.Not(faulty[d]))
            else:
                block.append(faulty[d])
        if not block:
            break
        solver.add(z3.Or(block))

    # faults forced / possible
    all_dom = set(range(nd))
    if fault_sets:
        poss_idx = set().union(*fault_sets)
        forc_idx = set.intersection(*[set(fs) for fs in fault_sets])
    else:
        poss_idx = set()
        forc_idx = set()
    possible = [domains[d] for d in range(nd) if d in poss_idx]
    forced = [domains[d] for d in range(nd) if d in forc_idx]

    # witness demands
    w_demands = [[int(witness_model.eval(q[s][ci], model_completion=True).as_long())
                  for ci in range(nc)] for s in range(ns)]
    w_links, w_faults = _compute_derived(req, coeff, L, w_demands)

    # distinct signatures per snapshot
    Ds = []
    for s in range(ns):
        ds = set()
        for o in snapshots[s]['observations']:
            if o['domain'] is not None:
                ds.add(domain_index[o['domain']])
        Ds.append(ds)
    sigs = [set() for _ in range(ns)]
    for fs in fault_sets:
        for s in range(ns):
            sigs[s].add(frozenset(fs & Ds[s]))

    # ranges per snapshot over union of signatures
    demand_ranges = [[None] * nc for _ in range(ns)]
    link_ranges = [[None] * ne for _ in range(ns)]
    for s in range(ns):
        for ci in range(nc):
            demand_ranges[s][ci] = None
        for e in range(ne):
            link_ranges[s][e] = None
        for A in sigs[s]:
            dmin, dmax, lmin, lmax = _snapshot_ranges(req, coeff, L, s, A)
            for ci in range(nc):
                if demand_ranges[s][ci] is None:
                    demand_ranges[s][ci] = [dmin[ci], dmax[ci]]
                else:
                    demand_ranges[s][ci][0] = min(demand_ranges[s][ci][0], dmin[ci])
                    demand_ranges[s][ci][1] = max(demand_ranges[s][ci][1], dmax[ci])
            for e in range(ne):
                if link_ranges[s][e] is None:
                    link_ranges[s][e] = [lmin[e], lmax[e]]
                else:
                    if lmin[e] < link_ranges[s][e][0]:
                        link_ranges[s][e][0] = lmin[e]
                    if lmax[e] > link_ranges[s][e][1]:
                        link_ranges[s][e][1] = lmax[e]

    unique = all(demand_ranges[s][ci][0] == demand_ranges[s][ci][1]
                 for s in range(ns) for ci in range(nc))

    # verdicts
    def sat_with(extra):
        sol = z3.Solver()
        sol.add(base_k)
        sol.add(extra)
        return sol.check() == z3.sat

    verdicts = []
    for s in range(ns):
        ctrl = snapshots[s]['controller']
        tol = snapshots[s]['tolerance']
        if nc == 0:
            agree_exists = True
            disagree_exists = False
        else:
            disj_agree = []
            disj_dis = []
            for ci in range(nc):
                disj_agree.append(z3.And(q[s][ci] >= ctrl[ci] - tol, q[s][ci] <= ctrl[ci] + tol))
                disj_dis.append(z3.Or(q[s][ci] < ctrl[ci] - tol, q[s][ci] > ctrl[ci] + tol))
            agree = z3.And(disj_agree)
            disagree = z3.Or(disj_dis)
            agree_exists = sat_with(agree)
            disagree_exists = sat_with(disagree)
        if disagree_exists and not agree_exists:
            v = 'inconsistent'
        elif agree_exists and not disagree_exists:
            v = 'consistent'
        else:
            v = 'undetermined'
        verdicts.append(v)

    # alternative
    alternative = None
    if not unique:
        diff = None
        for s in range(ns):
            for ci in range(nc):
                neq = q[s][ci] != w_demands[s][ci]
                diff = neq if diff is None else z3.Or(diff, neq)
        sol = z3.Solver()
        sol.add(base_k)
        sol.add(diff)
        if sol.check() == z3.sat:
            m2 = sol.model()
            a_demands = [[int(m2.eval(q[s][ci], model_completion=True).as_long())
                          for ci in range(nc)] for s in range(ns)]
            if a_demands != w_demands:
                a_links, a_faults = _compute_derived(req, coeff, L, a_demands)
                alternative = {'demands': a_demands, 'links': _links_str(a_links), 'faults': a_faults}

    snap_out = []
    for s in range(ns):
        dem = [[demand_ranges[s][ci][0], demand_ranges[s][ci][1]] for ci in range(nc)]
        lnk = [[frac_str(link_ranges[s][e][0]), frac_str(link_ranges[s][e][1])] for e in range(ne)]
        snap_out.append({'id': snapshots[s]['id'], 'demands': dem, 'links': lnk,
                         'verdict': verdicts[s]})

    return {
        'id': req['id'],
        'status': 'unique' if unique else 'ambiguous',
        'min_faults': k,
        'faults': {'forced': forced, 'possible': possible},
        'snapshots': snap_out,
        'witness': {'demands': w_demands, 'links': _links_str(w_links), 'faults': w_faults},
        'alternative': alternative,
    }


def _snapshot_ranges(req, coeff, L, s, A):
    """Exact min/max (integer for demands, Fraction for links) over the pure-LIA
    polytope of snapshot s where domains in A are relaxed."""
    edges = req['edges']
    edge_ids = req['edge_ids']
    snapshots = req['snapshots']
    commodities = req['commodities']
    comm_ids = req['comm_ids']
    domains = req['domains']
    domain_index = {d: i for i, d in enumerate(domains)}
    nc = len(comm_ids)
    ne = len(edge_ids)
    snap = snapshots[s]
    xs = [z3.Int('xs_%d' % ci) for ci in range(nc)]
    cons = []
    for ci in range(nc):
        lo, hi = snap['bounds'][ci]
        cons.append(xs[ci] >= lo)
        cons.append(xs[ci] <= hi)
    for e in range(ne):
        cap = edges[e]['capacity']
        expr = _link_expr(xs, coeff, e, nc)
        if expr is not None:
            cons.append(expr <= L * cap)
    for o in snap['observations']:
        if o['domain'] is not None and domain_index[o['domain']] in A:
            continue
        expr = _obs_expr_L(req, xs, coeff, L, s, o['metric'], o['target'])
        cons.append(z3.And(expr >= L * o['lo'], expr <= L * o['hi']))

    dmin = [0] * nc
    dmax = [0] * nc
    for ci in range(nc):
        lo, hi = snap['bounds'][ci]
        if lo == hi:
            dmin[ci] = dmax[ci] = lo
        else:
            dmin[ci] = _opt_cons(cons, xs[ci], True)
            dmax[ci] = _opt_cons(cons, xs[ci], False)
    lmin = [None] * ne
    lmax = [None] * ne
    for e in range(ne):
        expr = _link_expr(xs, coeff, e, nc)
        if expr is None:
            lmin[e] = lmax[e] = Fraction(0)
            continue
        mn = _opt_cons(cons, expr, True)
        mx = _opt_cons(cons, expr, False)
        lmin[e] = Fraction(mn, L)
        lmax[e] = Fraction(mx, L)
    return dmin, dmax, lmin, lmax


def _opt_cons(cons, expr, minimize):
    o = z3.Optimize()
    o.add(cons)
    if minimize:
        h = o.minimize(expr)
    else:
        h = o.maximize(expr)
    if o.check() != z3.sat:
        raise RuntimeError('unexpected unsat in range')
    # model is optimal; use evaluated value for exactness
    return int(o.model().eval(expr, model_completion=True).as_long())


def _compute_derived(req, coeff, L, demands):
    edges = req['edges']
    edge_ids = req['edge_ids']
    commodities = req['commodities']
    comm_ids = req['comm_ids']
    domains = req['domains']
    ns = len(req['snapshots'])
    nc = len(comm_ids)
    ne = len(edge_ids)
    nodes = req['nodes']

    links = []
    faults = set()
    for s in range(ns):
        qv = demands[s]
        loads = [Fraction(0) for _ in range(ne)]
        for ci in range(nc):
            for e in range(ne):
                cf = coeff[ci][e]
                if cf:
                    loads[e] += Fraction(cf, L) * qv[ci]
        metrics = {}
        for ci in range(nc):
            metrics[('demand', comm_ids[ci])] = Fraction(qv[ci])
        for n in nodes:
            ing = sum(qv[ci] for ci, c in enumerate(commodities) if c['source'] == n)
            egr = sum(qv[ci] for ci, c in enumerate(commodities) if c['target'] == n)
            metrics[('ingress', n)] = Fraction(ing)
            metrics[('egress', n)] = Fraction(egr)
        for e in range(ne):
            metrics[('link', edge_ids[e])] = loads[e]
        for o in req['snapshots'][s]['observations']:
            val = metrics[(o['metric'], o['target'])]
            if not (o['lo'] <= val <= o['hi']):
                if o['domain'] is not None:
                    faults.add(o['domain'])
        links.append(loads)
    return links, [d for d in domains if d in faults]


def _links_str(links):
    return [[frac_str(v) for v in row] for row in links]


def main():
    out = sys.stdout
    for line in sys.stdin:
        kind, val = parse_line(line)
        if kind == 'malformed':
            out.write(json.dumps({"id": None, "status": "error", "error": "malformed_json"}) + "\n")
            out.flush()
            continue
        rid = None
        if isinstance(val, dict) and is_name(val.get('id')):
            rid = val.get('id')
        try:
            norm = validate(val)
        except Invalid:
            out.write(json.dumps({"id": rid, "status": "error", "error": "invalid_instance"}) + "\n")
            out.flush()
            continue
        except Exception:
            out.write(json.dumps({"id": rid, "status": "error", "error": "invalid_instance"}) + "\n")
            out.flush()
            continue
        try:
            result = solve(norm)
            out.write(json.dumps(result) + "\n")
            out.flush()
        except Exception as e:
            sys.stderr.write("internal error: %r\n" % (e,))
            out.write(json.dumps({"id": norm['id'], "status": "infeasible"}) + "\n")
            out.flush()


if __name__ == '__main__':
    main()
